package io.knowledgebrain.collaboration;
import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.server.ResponseStatusException;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class ReviewEventTargetIntegrationTest {
 FeedbackRetractionStoreIntegrationTest f;ReviewEventTargetStore store;
 @BeforeEach void setup(){f=new FeedbackRetractionStoreIntegrationTest();f.setup();store=new ReviewEventTargetStore(f.f.f.f.source,f.f.f.store);}
 UUID event(UUID aggregate){return f.f.f.f.jdbc.queryForObject("SELECT id FROM outbox_event WHERE aggregateid=? ORDER BY id DESC LIMIT 1",UUID.class,aggregate);}
 ReviewEventTargetStore.Target get(UUID event,UUID actor,boolean owner){return store.get(f.f.f.group,f.f.f.space,f.f.f.study,f.f.f.assignment,f.f.answer.submissionId(),actor,owner,event);}
 @Test void historicalFeedbackRetractionTargetsExactOldReviewAfterNewFeedbackAndResubmission(){var marker=f.change(1,0,"RETRACTED","SECRET RETRACTION REASON");UUID event=event(marker.retractionId());f.f.change(1,1,"NEW PRIVATE OPINION");f.f.f.submit(f.f.f.f.key(),1,2,"NEW PRIVATE ANSWER");var v=get(event,f.f.f.author,false);assertEquals("FEEDBACK_RETRACTED",v.kind());assertEquals(1,v.reviewVersion());assertEquals(f.feedback.feedbackId(),v.reviewId());assertEquals(marker.retractionId(),v.sourceAggregateId());assertEquals(1,v.submissionVersion());assertEquals(v,get(event,f.f.f.f.owner,true));String json=tools.jackson.databind.json.JsonMapper.builder().build().writeValueAsString(v);assertFalse(json.contains("SECRET"));assertFalse(json.contains("content"));assertFalse(json.contains("reason"));assertEquals(2,f.f.get(f.f.f.author,false).feedback().version());}
 @Test void peerWrongGroupParentSubmissionAndEventCannotResolvePrivateProvenance(){var marker=f.change(1,0,"RETRACTED","Reason");var e=event(marker.retractionId());assertThrows(ResponseStatusException.class,()->get(e,f.f.f.f.ids.next(),false));assertThrows(ResponseStatusException.class,()->get(f.f.f.f.ids.next(),f.f.f.author,false));assertThrows(ResponseStatusException.class,()->store.get(f.f.f.f.ids.next(),f.f.f.space,f.f.f.study,f.f.f.assignment,f.f.answer.submissionId(),f.f.f.author,false,e));assertThrows(ResponseStatusException.class,()->store.get(f.f.f.group,f.f.f.space,f.f.f.study,f.f.f.f.ids.next(),f.f.answer.submissionId(),f.f.f.author,false,e));}
 @Test void originalFeedbackAndRestorationRemainDistinctImmutableSources(){var original=get(event(f.feedback.feedbackId()),f.f.f.author,false);assertEquals("FEEDBACK",original.kind());assertEquals(f.feedback.feedbackId(),original.reviewId());var marker=f.change(1,0,"RETRACTED","Reason");var withdrawn=get(event(marker.retractionId()),f.f.f.author,false);f.change(1,1,"RESTORED","Reviewed again");var restored=get(event(marker.retractionId()),f.f.f.author,false);assertEquals("FEEDBACK_RESTORED",restored.kind());assertEquals(2,restored.sourceVersion());assertEquals(1,restored.reviewVersion());assertEquals(withdrawn.reviewId(),restored.reviewId());assertEquals(withdrawn,get(withdrawn.sourceEventId(),f.f.f.author,false));}
 @Test void historicalGradeMarkerNeverTargetsNewGrade(){var g=new GradeRetractionStoreIntegrationTest();g.setup();var marker=g.change(1,0,"RETRACTED","PRIVATE REASON");var event=g.f.f.f.jdbc.queryForObject("SELECT id FROM outbox_event WHERE aggregateid=?",UUID.class,marker.retractionId());g.f.change(1,1,"NEW CURRENT GRADE");var target=new ReviewEventTargetStore(g.f.f.f.source,g.f.f.store).get(g.f.f.group,g.f.f.space,g.f.f.study,g.f.f.assignment,g.f.answer.submissionId(),g.f.f.author,false,event);assertEquals("GRADE_RETRACTED",target.kind());assertEquals(g.grade.gradeId(),target.reviewId());assertEquals(1,target.reviewVersion());assertEquals(1,target.submissionVersion());assertEquals(2,g.f.get(g.f.f.author,false).grade().version());}
 @Test void archivedAssignmentRetainsSourceReadWithoutMutations(){var marker=f.change(1,0,"RETRACTED","Reason");var event=event(marker.retractionId());f.f.f.parent.store.state(f.f.f.group,f.f.f.space,f.f.f.study,f.f.f.assignment,f.f.f.f.owner,2,"RETIRED",f.f.f.f.trace);assertEquals(1,get(event,f.f.f.author,false).reviewVersion());assertEquals(1,f.history(1,Long.MAX_VALUE,5).items().size());}

 @Test void canonicalRecoveryExportIncludesBothLifecycleFamiliesWithOriginalHashes(){var fb=f.change(1,0,"RETRACTED","PRIVATE RECOVERY FEEDBACK REASON");var feedbackEvent=event(fb.retractionId());var g=new GradeRetractionStoreIntegrationTest();g.setup();var gr=g.change(1,0,"RETRACTED","PRIVATE RECOVERY GRADE REASON");var gradeEvent=g.f.f.f.jdbc.queryForObject("SELECT id FROM outbox_event WHERE aggregateid=?",UUID.class,gr.retractionId());var expected=Set.of(feedbackEvent,gradeEvent);UUID earliest=expected.stream().min(java.util.Comparator.comparing(UUID::toString)).orElseThrow();UUID after=new UUID(earliest.getMostSignificantBits(),earliest.getLeastSignificantBits()-1);var export=new ReviewSignalExportController(f.f.f.f.source,"a".repeat(43));var found=new HashSet<UUID>();do{var page=export.page(after,100);for(var item:page.items())if(expected.contains(item.eventId())){var bytes=f.f.f.f.jdbc.queryForObject("SELECT payload FROM outbox_event WHERE id=?",byte[].class,item.eventId());assertEquals(ReviewSignal.hash(bytes),item.payloadHash());assertTrue(Set.of("FEEDBACK_RETRACTED","GRADE_RETRACTED").contains(item.kind()));String json=tools.jackson.databind.json.JsonMapper.builder().build().writeValueAsString(item);assertFalse(json.contains("PRIVATE RECOVERY"));found.add(item.eventId());}after=page.nextAfter();}while(after!=null&&!found.containsAll(expected));assertEquals(expected,found);}
}
